'@
$compressedDatabase = [Convert]::FromBase64String($embeddedDatabaseBase64)
$inputStream = New-Object System.IO.MemoryStream(,$compressedDatabase)
$gzipStream = New-Object System.IO.Compression.GZipStream(
    $inputStream,
    [System.IO.Compression.CompressionMode]::Decompress
)
$databaseReader = New-Object System.IO.StreamReader(
    $gzipStream,
    [System.Text.Encoding]::UTF8,
    $true
)
try {
    $global:embeddedDatabaseCsv = $databaseReader.ReadToEnd()
}
finally {
    $databaseReader.Dispose()
    $gzipStream.Dispose()
    $inputStream.Dispose()
}
Remove-Variable embeddedDatabaseBase64, compressedDatabase
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# ============================================================
# ONCE HUMAN ASSET EXPLORER V2.0
# ============================================================

$applicationDirectory = $PSScriptRoot

if ([string]::IsNullOrWhiteSpace($applicationDirectory)) {
    $applicationDirectory = Split-Path -Parent (
        [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
    )
}

$logoFile = Join-Path $applicationDirectory "assets\blachammer-logo.png"

$webView2Directory = Join-Path $applicationDirectory "WebView2"
$webView2CoreAssembly = Join-Path $webView2Directory "Microsoft.Web.WebView2.Core.dll"
$webView2FormsAssembly = Join-Path $webView2Directory "Microsoft.Web.WebView2.WinForms.dll"
$webView2RuntimeArchitecture = if ([IntPtr]::Size -eq 8) { "win-x64" } else { "win-x86" }
$webView2LoaderDirectory = Join-Path $webView2Directory "runtimes\$webView2RuntimeArchitecture\native"
$script:webView2Available = $false
$script:webView2LoadError = $null
$script:onlineMapInitializationStarted = $false
$script:pendingOnlineMapUrl = $null

try {
    foreach ($dependency in @(
        $webView2CoreAssembly,
        $webView2FormsAssembly,
        (Join-Path $webView2LoaderDirectory "WebView2Loader.dll")
    )) {
        if (-not (Test-Path -LiteralPath $dependency -PathType Leaf)) {
            throw "Required WebView2 dependency is missing: $dependency"
        }
    }

    $env:PATH = "$webView2LoaderDirectory;$env:PATH"
    Add-Type -Path $webView2CoreAssembly -ErrorAction Stop
    Add-Type -Path $webView2FormsAssembly -ErrorAction Stop
    $script:webView2Available = $true
}
catch {
    $script:webView2LoadError = $_.Exception.Message
}

$databaseFile = Join-Path $applicationDirectory "OnceHuman_EnhancedDatabase.csv"

if (
    [string]::IsNullOrWhiteSpace($global:embeddedDatabaseCsv) -and
    -not (Test-Path $databaseFile)
) {
    [System.Windows.Forms.MessageBox]::Show(
        "Database not found:`n$databaseFile",
        "Once Human Asset Explorer",
        "OK",
        "Error"
    )
    exit
}

if (-not (Test-Path -LiteralPath $logoFile -PathType Leaf)) {
    [System.Windows.Forms.MessageBox]::Show(
        "Application logo not found:`n$logoFile",
        "Once Human Asset Explorer",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Error
    )
    exit
}

if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
    throw "LOCALAPPDATA is not set. Cannot locate the manual asset database."
}

$userDataFolder = Join-Path $env:LOCALAPPDATA "OnceHumanAssetExplorer"
$manualDatabaseFile = Join-Path $userDataFolder "manual_items.csv"
$themeSettingsFile = Join-Path $userDataFolder "theme.json"
$mapsDirectory = Join-Path $userDataFolder "Maps"
$mapIndexFile = Join-Path $userDataFolder "maps.csv"
$mapMarkersFile = Join-Path $userDataFolder "map_markers.csv"
$legacyManualDatabaseFile = Join-Path $applicationDirectory "manual_items.csv"

New-Item `
    -ItemType Directory `
    -Path $userDataFolder, $mapsDirectory `
    -Force `
    -ErrorAction Stop |
    Out-Null

if (
    -not (Test-Path $manualDatabaseFile) -and
    (Test-Path $legacyManualDatabaseFile) -and
    [IO.Path]::GetFullPath($legacyManualDatabaseFile) -ne
        [IO.Path]::GetFullPath($manualDatabaseFile)
) {
    Copy-Item `
        -LiteralPath $legacyManualDatabaseFile `
        -Destination $manualDatabaseFile `
        -ErrorAction Stop
}

# ------------------------------------------------------------
# LOAD DATABASES
# ------------------------------------------------------------

if (
    -not (Test-Path $manualDatabaseFile) -or
    (Get-Item $manualDatabaseFile).Length -eq 0
) {
    Set-Content `
        -LiteralPath $manualDatabaseFile `
        -Value "Category,SubCategory,AssetName,DisplayName,Source,SearchTerms,Notes" `
        -Encoding UTF8
}

if (-not (Test-Path -LiteralPath $mapIndexFile)) {
    Set-Content `
        -LiteralPath $mapIndexFile `
        -Value "MapId,Name,Version,ImageFile,DateAdded" `
        -Encoding UTF8
}

if (-not (Test-Path -LiteralPath $mapMarkersFile)) {
    Set-Content `
        -LiteralPath $mapMarkersFile `
        -Value "MarkerId,MapId,Name,Type,Notes,X,Y,DateAdded" `
        -Encoding UTF8
}

function Load-AssetDatabase {

    if ([string]::IsNullOrWhiteSpace($global:embeddedDatabaseCsv)) {
        $generated = @(Import-Csv -LiteralPath $databaseFile)
    }
    else {
        $generated = @(
            ConvertFrom-Csv -InputObject $global:embeddedDatabaseCsv
        )
    }

    $manual = @(
        Import-Csv -LiteralPath $manualDatabaseFile |
            Where-Object {
                -not [string]::IsNullOrWhiteSpace($_.AssetName)
            }
    )

    return @($generated) + @($manual)
}

function Save-ManualDatabase {

    param(
        [AllowEmptyCollection()]
        [object[]]$Records
    )

    $columns = @(
        "Category",
        "SubCategory",
        "AssetName",
        "DisplayName",
        "Source",
        "SearchTerms",
        "Notes"
    )

    $temporaryFile = "$manualDatabaseFile.$PID.$([guid]::NewGuid().ToString('N')).tmp"

    try {
        if ($null -eq $Records -or $Records.Count -eq 0) {
            Set-Content `
                -LiteralPath $temporaryFile `
                -Value ($columns -join ",") `
                -Encoding UTF8 `
                -ErrorAction Stop
        }
        else {
            @($Records) |
                Select-Object -Property $columns |
                Export-Csv `
                    -LiteralPath $temporaryFile `
                    -NoTypeInformation `
                    -Encoding UTF8 `
                    -ErrorAction Stop
        }

        Move-Item `
            -LiteralPath $temporaryFile `
            -Destination $manualDatabaseFile `
            -Force `
            -ErrorAction Stop
    }
    finally {
        if (Test-Path -LiteralPath $temporaryFile) {
            Remove-Item -LiteralPath $temporaryFile -ErrorAction SilentlyContinue
        }
    }
}

function Reload-AssetDatabase {

    $script:db = @(Load-AssetDatabase)
    Update-CategoryList
    Update-SubCategoryList
    Update-Results
}

function Find-ManualRecordIndex {

    param(
        [Parameter(Mandatory = $true)]
        [object]$Record,
        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [object[]]$ManualRecords
    )

    for ($index = 0; $index -lt $ManualRecords.Count; $index++) {
        $candidate = $ManualRecords[$index]

        if (
            $candidate.Source -eq "Manual" -and
            $candidate.AssetName -ieq $Record.AssetName -and
            $candidate.DisplayName -eq $Record.DisplayName -and
            $candidate.Category -eq $Record.Category -and
            $candidate.SubCategory -eq $Record.SubCategory -and
            $candidate.SearchTerms -eq $Record.SearchTerms -and
            $candidate.Notes -eq $Record.Notes
        ) {
            return $index
        }
    }

    return -1
}

function Get-SelectedAssetRecord {

    if ($grid.SelectedRows.Count -eq 0) {
        return $null
    }

    $recordIndex = [int]$grid.SelectedRows[0].Cells["RecordIndex"].Value

    if (
        $recordIndex -lt 0 -or
        $recordIndex -ge $script:currentResults.Count
    ) {
        return $null
    }

    return $script:currentResults[$recordIndex]
}

$script:defaultTheme = [PSCustomObject]@{
    Background = "#1C1E22"
    Foreground = "#FFFFFF"
    Accent     = "#50C8FF"
    FontSize   = 10
    Opacity    = 100
}

$script:theme = $script:defaultTheme.PSObject.Copy()

if (Test-Path -LiteralPath $themeSettingsFile) {
    try {
        $storedTheme = Get-Content -LiteralPath $themeSettingsFile -Raw -ErrorAction Stop |
            ConvertFrom-Json -ErrorAction Stop

        foreach ($property in @("Background", "Foreground", "Accent")) {
            $storedColor = [string]$storedTheme.$property
            if (-not [string]::IsNullOrWhiteSpace($storedColor)) {
                $parsedColor = [System.Drawing.ColorTranslator]::FromHtml($storedColor)
                if (-not $parsedColor.IsEmpty) {
                    $script:theme.$property = [string]::Format(
                        "#{0:X2}{1:X2}{2:X2}",
                        $parsedColor.R,
                        $parsedColor.G,
                        $parsedColor.B
                    )
                }
            }
        }

        if ($storedTheme.FontSize -ge 8 -and $storedTheme.FontSize -le 18) {
            $script:theme.FontSize = [int]$storedTheme.FontSize
        }

        if ($storedTheme.Opacity -ge 55 -and $storedTheme.Opacity -le 100) {
            $script:theme.Opacity = [int]$storedTheme.Opacity
        }
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Could not load appearance settings. Defaults will be used.`n`n$($_.Exception.Message)",
            "Appearance Settings",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        ) | Out-Null
    }
}

function Save-ThemeSettings {

    $temporaryFile = "$themeSettingsFile.$PID.$([guid]::NewGuid().ToString('N')).tmp"

    try {
        $script:theme |
            ConvertTo-Json |
            Set-Content -LiteralPath $temporaryFile -Encoding UTF8 -ErrorAction Stop

        Move-Item `
            -LiteralPath $temporaryFile `
            -Destination $themeSettingsFile `
            -Force `
            -ErrorAction Stop
    }
    finally {
        if (Test-Path -LiteralPath $temporaryFile) {
            Remove-Item -LiteralPath $temporaryFile -Force -ErrorAction SilentlyContinue
        }
    }
}

function Get-ThemeColor {

    param(
        [Parameter(Mandatory = $true)]
        [string]$Value
    )

    return [System.Drawing.ColorTranslator]::FromHtml($Value)
}

function Get-ThemeContrastColor {

    param(
        [Parameter(Mandatory = $true)]
        [System.Drawing.Color]$Color
    )

    $brightness = (0.299 * $Color.R) + (0.587 * $Color.G) + (0.114 * $Color.B)
    if ($brightness -ge 150) {
        return [System.Drawing.Color]::Black
    }

    return [System.Drawing.Color]::White
}

function Apply-ThemeToControl {

    param(
        [Parameter(Mandatory = $true)]
        [System.Windows.Forms.Control]$Control
    )

    $isWebViewControl = $Control.GetType().FullName -eq `
        "Microsoft.Web.WebView2.WinForms.WebView2"
    $backgroundColor = Get-ThemeColor $script:theme.Background
    $foregroundColor = Get-ThemeColor $script:theme.Foreground
    $accentColor = Get-ThemeColor $script:theme.Accent
    $surfaceColor = [System.Drawing.Color]::FromArgb(
        [Math]::Min(255, $backgroundColor.R + 12),
        [Math]::Min(255, $backgroundColor.G + 12),
        [Math]::Min(255, $backgroundColor.B + 12)
    )

    if ($Control -is [System.Windows.Forms.Form]) {
        $Control.BackColor = $backgroundColor
        $Control.Opacity = $script:theme.Opacity / 100.0
    }
    elseif ($Control -is [System.Windows.Forms.DataGridView]) {
        $Control.BackgroundColor = $backgroundColor
        $Control.ForeColor = $foregroundColor
        $Control.DefaultCellStyle.BackColor = $surfaceColor
        $Control.DefaultCellStyle.ForeColor = $foregroundColor
        $Control.DefaultCellStyle.SelectionBackColor = $accentColor
        $Control.DefaultCellStyle.SelectionForeColor = Get-ThemeContrastColor $accentColor
        $Control.ColumnHeadersDefaultCellStyle.BackColor = $backgroundColor
        $Control.ColumnHeadersDefaultCellStyle.ForeColor = $foregroundColor
        $Control.EnableHeadersVisualStyles = $false
        $Control.BackgroundColor = $backgroundColor
    }
    elseif ($Control -is [System.Windows.Forms.TextBoxBase] -or
            $Control -is [System.Windows.Forms.ComboBox] -or
            $Control -is [System.Windows.Forms.NumericUpDown]) {
        $Control.BackColor = $surfaceColor
        $Control.ForeColor = $foregroundColor
    }
    elseif ($Control -is [System.Windows.Forms.Button]) {
        if ($Control.Tag -in @("Background", "Foreground", "Accent")) {
            $Control.ForeColor = Get-ThemeContrastColor $Control.BackColor
        }
        elseif ($Control.Text -like "Delete*") {
            $Control.BackColor = [System.Drawing.Color]::FromArgb(145, 45, 45)
            $Control.ForeColor = [System.Drawing.Color]::White
        }
        else {
            $Control.BackColor = $accentColor
            $Control.ForeColor = Get-ThemeContrastColor $accentColor
        }
        $Control.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    }
    else {
        $Control.BackColor = $backgroundColor
        $Control.ForeColor = $foregroundColor
    }

    if ($Control.Font -and
        $Control -isnot [System.Windows.Forms.TrackBar] -and
        -not $isWebViewControl) {
        $fontStyle = $Control.Font.Style
        $Control.Font = New-Object System.Drawing.Font(
            $Control.Font.FontFamily,
            [single]$script:theme.FontSize,
            $fontStyle
        )
    }

    if (-not $isWebViewControl) {
        foreach ($child in $Control.Controls) {
            Apply-ThemeToControl -Control $child
        }
    }
}

function Apply-ApplicationTheme {
    Apply-ThemeToControl -Control $form
    $title.ForeColor = Get-ThemeColor $script:theme.Accent
    $countLabel.ForeColor = Get-ThemeColor $script:theme.Accent

    $grid.AlternatingRowsDefaultCellStyle.BackColor =
        [System.Drawing.Color]::FromArgb(
            [Math]::Min(255, $form.BackColor.R + 6),
            [Math]::Min(255, $form.BackColor.G + 6),
            [Math]::Min(255, $form.BackColor.B + 6)
        )
    $grid.AlternatingRowsDefaultCellStyle.ForeColor = Get-ThemeColor $script:theme.Foreground
}

$script:maps = @(
    Import-Csv -LiteralPath $mapIndexFile |
        Where-Object {
            -not [string]::IsNullOrWhiteSpace($_.MapId) -and
            (Test-Path -LiteralPath (Join-Path $mapsDirectory $_.ImageFile))
        }
)
$script:mapMarkers = @(
    Import-Csv -LiteralPath $mapMarkersFile |
        Where-Object {
            -not [string]::IsNullOrWhiteSpace($_.MarkerId)
        }
)
$script:activeMap = $null
$script:activeMapImage = $null
$script:isPlacingMapMarker = $false
$script:mapZoom = 1.0
$script:mapPanX = 0.0
$script:mapPanY = 0.0
$script:isPanningMap = $false
$script:mapPanStart = [System.Drawing.Point]::Empty
$script:mapPanStartOffsetX = 0.0
$script:mapPanStartOffsetY = 0.0
$script:mapPanDragged = $false

function Save-MapCsv {

    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,
        [Parameter(Mandatory = $true)]
        [string[]]$Columns,
        [AllowEmptyCollection()]
        [object[]]$Records
    )

    $temporaryFile = "$Path.$PID.$([guid]::NewGuid().ToString('N')).tmp"

    try {
        if ($null -eq $Records -or $Records.Count -eq 0) {
            Set-Content `
                -LiteralPath $temporaryFile `
                -Value ($Columns -join ",") `
                -Encoding UTF8 `
                -ErrorAction Stop
        }
        else {
            @($Records) |
                Select-Object -Property $Columns |
                Export-Csv `
                    -LiteralPath $temporaryFile `
                    -NoTypeInformation `
                    -Encoding UTF8 `
                    -ErrorAction Stop
        }

        Move-Item `
            -LiteralPath $temporaryFile `
            -Destination $Path `
            -Force `
            -ErrorAction Stop
    }
    finally {
        if (Test-Path -LiteralPath $temporaryFile) {
            Remove-Item -LiteralPath $temporaryFile -Force -ErrorAction SilentlyContinue
        }
    }
}

function Get-MapImageRectangle {

    param(
        [Parameter(Mandatory = $true)]
        [System.Windows.Forms.Control]$Canvas,
        [Parameter(Mandatory = $true)]
        [System.Drawing.Image]$Image,
        [double]$Zoom = 1.0,
        [double]$PanX = 0.0,
        [double]$PanY = 0.0
    )

    if ($Image.Width -le 0 -or $Image.Height -le 0 -or
        $Canvas.ClientSize.Width -le 0 -or $Canvas.ClientSize.Height -le 0) {
        return [System.Drawing.RectangleF]::Empty
    }

    $scale = [Math]::Min(
        $Canvas.ClientSize.Width / [double]$Image.Width,
        $Canvas.ClientSize.Height / [double]$Image.Height
    )
    $fitWidth = [single]($Image.Width * $scale)
    $fitHeight = [single]($Image.Height * $scale)
    $width = [single]($fitWidth * $Zoom)
    $height = [single]($fitHeight * $Zoom)
    $left = [single]((($Canvas.ClientSize.Width - $fitWidth) / 2) + $PanX + (($fitWidth - $width) / 2))
    $top = [single]((($Canvas.ClientSize.Height - $fitHeight) / 2) + $PanY + (($fitHeight - $height) / 2))

    return [System.Drawing.RectangleF]::new($left, $top, $width, $height)
}

function Set-MapZoom {

    param(
        [Parameter(Mandatory = $true)]
        [double]$Zoom,
        [double]$FocusX = -1,
        [double]$FocusY = -1
    )

    if ($null -eq $script:activeMapImage) {
        return
    }

    $Zoom = [Math]::Max(1.0, [Math]::Min(8.0, $Zoom))
    if ($FocusX -lt 0) {
        $FocusX = $mapCanvas.ClientSize.Width / 2.0
    }
    if ($FocusY -lt 0) {
        $FocusY = $mapCanvas.ClientSize.Height / 2.0
    }

    $oldRectangle = Get-MapImageRectangle `
        -Canvas $mapCanvas `
        -Image $script:activeMapImage `
        -Zoom $script:mapZoom `
        -PanX $script:mapPanX `
        -PanY $script:mapPanY
    if ($oldRectangle.Width -le 0 -or $oldRectangle.Height -le 0) {
        return
    }

    $mapX = ($FocusX - $oldRectangle.X) / $oldRectangle.Width
    $mapY = ($FocusY - $oldRectangle.Y) / $oldRectangle.Height
    $script:mapZoom = $Zoom

    $fitRectangle = Get-MapImageRectangle `
        -Canvas $mapCanvas `
        -Image $script:activeMapImage
    $script:mapPanX = $FocusX - ($mapX * $fitRectangle.Width * $Zoom) -
        (($mapCanvas.ClientSize.Width - $fitRectangle.Width) / 2.0) -
        (($fitRectangle.Width - ($fitRectangle.Width * $Zoom)) / 2.0)
    $script:mapPanY = $FocusY - ($mapY * $fitRectangle.Height * $Zoom) -
        (($mapCanvas.ClientSize.Height - $fitRectangle.Height) / 2.0) -
        (($fitRectangle.Height - ($fitRectangle.Height * $Zoom)) / 2.0)

    if ($script:mapZoom -le 1.0) {
        $script:mapPanX = 0.0
        $script:mapPanY = 0.0
    }

    $mapCanvas.Invalidate()
}

function Update-MapSelector {

    $selectedMapId = if ($null -ne $script:activeMap) {
        [string]$script:activeMap.MapId
    }
    else {
        $null
    }

    $mapSelector.Items.Clear()

    for ($index = 0; $index -lt $script:maps.Count; $index++) {
        $map = $script:maps[$index]
        [void]$mapSelector.Items.Add("$($map.Name) — $($map.Version)")
        if ($map.MapId -eq $selectedMapId) {
            $mapSelector.SelectedIndex = $index
        }
    }

    if ($mapSelector.SelectedIndex -lt 0 -and $mapSelector.Items.Count -gt 0) {
        $mapSelector.SelectedIndex = 0
    }
    elseif ($mapSelector.Items.Count -eq 0) {
        Load-SelectedMap
    }
}

function Update-MapMarkerList {

    $mapMarkerList.Items.Clear()
    $mapMarkerDetails.Clear()

    if ($null -eq $script:activeMap) {
        return
    }

    foreach ($marker in @(Get-VisibleMapMarkers)) {
        $listItem = New-Object System.Windows.Forms.ListViewItem([string]$marker.Name)
        [void]$listItem.SubItems.Add([string]$marker.Type)
        [void]$listItem.SubItems.Add(
            ("{0:P0}" -f [double]::Parse(
                [string]$marker.X,
                [Globalization.CultureInfo]::InvariantCulture
            ))
        )
        [void]$listItem.SubItems.Add(
            ("{0:P0}" -f [double]::Parse(
                [string]$marker.Y,
                [Globalization.CultureInfo]::InvariantCulture
            ))
        )
        $listItem.Tag = [string]$marker.MarkerId
        [void]$mapMarkerList.Items.Add($listItem)
    }

    $mapMarkerList.Invalidate()
    $mapCanvas.Invalidate()
}

function Get-VisibleMapMarkers {

    if ($null -eq $script:activeMap) {
        return @()
    }

    $searchText = [string]$mapMarkerSearch.Text
    return @(
        $script:mapMarkers | Where-Object {
            if ($_.MapId -ne $script:activeMap.MapId) {
                return $false
            }

            if ([string]::IsNullOrWhiteSpace($searchText)) {
                return $true
            }

            foreach ($value in @($_.Name, $_.Type, $_.Notes)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$value) -and
                    ([string]$value).IndexOf(
                        $searchText,
                        [StringComparison]::OrdinalIgnoreCase
                    ) -ge 0) {
                    return $true
                }
            }

            return $false
        }
    )
}

function Load-SelectedMap {

    if ($null -ne $script:activeMapImage) {
        $script:activeMapImage.Dispose()
        $script:activeMapImage = $null
    }

    $script:activeMap = $null
    $script:isPlacingMapMarker = $false
    $script:isPanningMap = $false
    $script:mapZoom = 1.0
    $script:mapPanX = 0.0
    $script:mapPanY = 0.0
    $placeMapMarkerButton.Enabled = $false

    if ($mapSelector.SelectedIndex -lt 0 -or
        $mapSelector.SelectedIndex -ge $script:maps.Count) {
        $mapZoomInButton.Enabled = $false
        $mapZoomOutButton.Enabled = $false
        $mapFitButton.Enabled = $false
        $mapCanvas.Invalidate()
        Update-MapMarkerList
        return
    }

    $script:activeMap = $script:maps[$mapSelector.SelectedIndex]
    $script:mapZoom = 1.0
    $script:mapPanX = 0.0
    $script:mapPanY = 0.0
    $imagePath = Join-Path $mapsDirectory $script:activeMap.ImageFile

    try {
        $sourceImage = [System.Drawing.Image]::FromFile($imagePath)
        try {
            $script:activeMapImage = New-Object System.Drawing.Bitmap($sourceImage)
        }
        finally {
            $sourceImage.Dispose()
        }
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Could not load the selected map image:`n$($_.Exception.Message)",
            "Map Load Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
        $script:activeMap = $null
        $mapZoomInButton.Enabled = $false
        $mapZoomOutButton.Enabled = $false
        $mapFitButton.Enabled = $false
        $mapCanvas.Invalidate()
        Update-MapMarkerList
        return
    }

    $placeMapMarkerButton.Enabled = $true
    $mapZoomInButton.Enabled = $true
    $mapZoomOutButton.Enabled = $true
    $mapFitButton.Enabled = $true
    $mapCanvas.Invalidate()
    Update-MapMarkerList
}

function Show-MapImportDialog {

    param(
        [Parameter(Mandatory = $true)]
        [string]$ImagePath
    )

    if (-not (Test-Path -LiteralPath $ImagePath -PathType Leaf)) {
        throw "Map image not found: $ImagePath"
    }

    $mapForm = New-Object System.Windows.Forms.Form
    $mapForm.Text = "Add Map Image"
    $mapForm.Size = New-Object System.Drawing.Size(500, 300)
    $mapForm.StartPosition = "CenterParent"
    $mapForm.FormBorderStyle = "FixedDialog"
    $mapForm.MaximizeBox = $false
    $mapForm.MinimizeBox = $false

    $mapNameLabel = New-Object System.Windows.Forms.Label
    $mapNameLabel.Text = "Map name or region"
    $mapNameLabel.Location = New-Object System.Drawing.Point(20, 25)
    $mapNameLabel.AutoSize = $true
    $mapForm.Controls.Add($mapNameLabel)

    $mapNameBox = New-Object System.Windows.Forms.TextBox
    $mapNameBox.Location = New-Object System.Drawing.Point(20, 48)
    $mapNameBox.Size = New-Object System.Drawing.Size(440, 26)
    $mapNameBox.Text = [IO.Path]::GetFileNameWithoutExtension($ImagePath)
    $mapForm.Controls.Add($mapNameBox)

    $mapVersionLabel = New-Object System.Windows.Forms.Label
    $mapVersionLabel.Text = "Scenario or game version"
    $mapVersionLabel.Location = New-Object System.Drawing.Point(20, 90)
    $mapVersionLabel.AutoSize = $true
    $mapForm.Controls.Add($mapVersionLabel)

    $mapVersionBox = New-Object System.Windows.Forms.TextBox
    $mapVersionBox.Location = New-Object System.Drawing.Point(20, 113)
    $mapVersionBox.Size = New-Object System.Drawing.Size(440, 26)
    $mapVersionBox.Text = "Nalcott"
    $mapForm.Controls.Add($mapVersionBox)

    $mapFileLabel = New-Object System.Windows.Forms.Label
    $mapFileLabel.Text = "Image: $([IO.Path]::GetFileName($ImagePath))"
    $mapFileLabel.Location = New-Object System.Drawing.Point(20, 155)
    $mapFileLabel.Size = New-Object System.Drawing.Size(440, 35)
    $mapForm.Controls.Add($mapFileLabel)

    $saveMapButton = New-Object System.Windows.Forms.Button
    $saveMapButton.Text = "Add Map"
    $saveMapButton.Location = New-Object System.Drawing.Point(20, 205)
    $saveMapButton.Size = New-Object System.Drawing.Size(120, 35)
    $mapForm.Controls.Add($saveMapButton)

    $cancelMapButton = New-Object System.Windows.Forms.Button
    $cancelMapButton.Text = "Cancel"
    $cancelMapButton.Location = New-Object System.Drawing.Point(155, 205)
    $cancelMapButton.Size = New-Object System.Drawing.Size(100, 35)
    $mapForm.Controls.Add($cancelMapButton)

    $saveMapButton.Add_Click({
        $name = $mapNameBox.Text.Trim()
        $version = $mapVersionBox.Text.Trim()

        if ([string]::IsNullOrWhiteSpace($name) -or
            [string]::IsNullOrWhiteSpace($version)) {
            [System.Windows.Forms.MessageBox]::Show(
                "Enter both a map name and a scenario/version.",
                "Map Details Required",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Warning
            ) | Out-Null
            return
        }

        $testImage = $null
        try {
            $testImage = [System.Drawing.Image]::FromFile($ImagePath)
            if ($testImage.Width -lt 100 -or $testImage.Height -lt 100) {
                throw "The selected image is too small to use as a map."
            }
        }
        catch {
            [System.Windows.Forms.MessageBox]::Show(
                "The selected file is not a usable map image:`n$($_.Exception.Message)",
                "Invalid Map Image",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
            return
        }
        finally {
            if ($null -ne $testImage) {
                $testImage.Dispose()
            }
        }

        $mapId = [guid]::NewGuid().ToString("N")
        $extension = [IO.Path]::GetExtension($ImagePath).ToLowerInvariant()
        $storedImageName = "$mapId$extension"
        $storedImagePath = Join-Path $mapsDirectory $storedImageName

        try {
            Copy-Item -LiteralPath $ImagePath -Destination $storedImagePath -ErrorAction Stop
            $newMap = [PSCustomObject]@{
                MapId = $mapId
                Name = $name
                Version = $version
                ImageFile = $storedImageName
                DateAdded = (Get-Date).ToString("o")
            }

            Save-MapCsv `
                -Path $mapIndexFile `
                -Columns @("MapId", "Name", "Version", "ImageFile", "DateAdded") `
                -Records @($script:maps + $newMap)
        }
        catch {
            if (Test-Path -LiteralPath $storedImagePath) {
                Remove-Item -LiteralPath $storedImagePath -Force -ErrorAction SilentlyContinue
            }
            [System.Windows.Forms.MessageBox]::Show(
                "Could not add the map:`n$($_.Exception.Message)",
                "Map Import Failed",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
            return
        }

        $mapForm.Tag = $mapId
        $mapForm.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $mapForm.Close()
    }.GetNewClosure())

    $cancelMapButton.Add_Click({
        $mapForm.Close()
    }.GetNewClosure())

    Apply-ThemeToControl -Control $mapForm
    if ($mapForm.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
        $newMapId = [string]$mapForm.Tag
        $script:maps = @(
            Import-Csv -LiteralPath $mapIndexFile |
                Where-Object {
                    -not [string]::IsNullOrWhiteSpace($_.MapId) -and
                    (Test-Path -LiteralPath (Join-Path $mapsDirectory $_.ImageFile))
                }
        )
        Update-MapSelector
        for ($index = 0; $index -lt $script:maps.Count; $index++) {
            if ($script:maps[$index].MapId -eq $newMapId) {
                $mapSelector.SelectedIndex = $index
                break
            }
        }
        Load-SelectedMap
    }
}

