            Save-MapCsv `
                -Path $mapMarkersFile `
                -Columns @("MarkerId", "MapId", "Name", "Type", "Notes", "X", "Y", "DateAdded") `
                -Records $updatedMarkers
            $script:mapMarkers = $updatedMarkers
        }
        catch {
            [System.Windows.Forms.MessageBox]::Show(
                "Could not save the map marker:`n$($_.Exception.Message)",
                "Marker Save Failed",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
            return
        }

        $markerForm.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $markerForm.Close()
    }.GetNewClosure())

    $cancelMarkerButton.Add_Click({
        $markerForm.Close()
    }.GetNewClosure())

    Apply-ThemeToControl -Control $markerForm
    if ($markerForm.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
        Update-MapMarkerList
    }
}

