    $accentLabel = New-Object System.Windows.Forms.Label
    $accentLabel.Text = "Accent and selection color"
    $accentLabel.Location = New-Object System.Drawing.Point(20, 155)
    $accentLabel.Size = New-Object System.Drawing.Size(250, 25)
    $appearanceForm.Controls.Add($accentLabel)

    $accentButton = New-Object System.Windows.Forms.Button
    $accentButton.Text = "Choose..."
    $accentButton.Location = New-Object System.Drawing.Point(300, 150)
    $accentButton.Size = New-Object System.Drawing.Size(160, 32)
    $accentButton.BackColor = Get-ThemeColor $draftTheme.Accent
    $appearanceForm.Controls.Add($accentButton)

    $backgroundButton.Tag = "Background"
    $foregroundButton.Tag = "Foreground"
    $accentButton.Tag = "Accent"

    foreach ($colorButton in @($backgroundButton, $foregroundButton, $accentButton)) {
        $senderButton = $colorButton
        $colorButton.Add_Click({
            $picker = New-Object System.Windows.Forms.ColorDialog
            $picker.FullOpen = $true
            $picker.Color = $senderButton.BackColor
            if ($picker.ShowDialog($appearanceForm) -eq [System.Windows.Forms.DialogResult]::OK) {
                $senderButton.BackColor = $picker.Color
                $selectedHtml = [System.Drawing.ColorTranslator]::ToHtml($picker.Color)
                switch ($senderButton.Tag) {
                    "Background" { $draftTheme.Background = $selectedHtml }
                    "Foreground" { $draftTheme.Foreground = $selectedHtml }
                    "Accent" { $draftTheme.Accent = $selectedHtml }
                }
            }
        }.GetNewClosure())
    }

    $fontSizeLabel = New-Object System.Windows.Forms.Label
    $fontSizeLabel.Text = "Text size"
    $fontSizeLabel.Location = New-Object System.Drawing.Point(20, 210)
