    $fontSizeInput.Maximum = 18
    $fontSizeInput.Value = $draftTheme.FontSize
    $appearanceForm.Controls.Add($fontSizeInput)

    $opacityLabel = New-Object System.Windows.Forms.Label
    $opacityLabel.Text = "Window opacity: $($draftTheme.Opacity)%"
    $opacityLabel.Location = New-Object System.Drawing.Point(20, 255)
    $opacityLabel.Size = New-Object System.Drawing.Size(250, 25)
    $appearanceForm.Controls.Add($opacityLabel)

    $opacityInput = New-Object System.Windows.Forms.TrackBar
    $opacityInput.Location = New-Object System.Drawing.Point(285, 245)
    $opacityInput.Size = New-Object System.Drawing.Size(190, 45)
    $opacityInput.Minimum = 55
    $opacityInput.Maximum = 100
    $opacityInput.TickFrequency = 5
    $opacityInput.Value = $draftTheme.Opacity
    $appearanceForm.Controls.Add($opacityInput)

    $opacityInput.Add_ValueChanged({
        $opacityLabel.Text = "Window opacity: $($opacityInput.Value)%"
    }.GetNewClosure())

    $saveAppearanceButton = New-Object System.Windows.Forms.Button
    $saveAppearanceButton.Text = "Save and Apply"
    $saveAppearanceButton.Location = New-Object System.Drawing.Point(20, 335)
    $saveAppearanceButton.Size = New-Object System.Drawing.Size(140, 35)
    $appearanceForm.Controls.Add($saveAppearanceButton)

    $resetAppearanceButton = New-Object System.Windows.Forms.Button
    $resetAppearanceButton.Text = "Reset Defaults"
    $resetAppearanceButton.Location = New-Object System.Drawing.Point(170, 335)
    $resetAppearanceButton.Size = New-Object System.Drawing.Size(130, 35)
    $appearanceForm.Controls.Add($resetAppearanceButton)

    $cancelAppearanceButton = New-Object System.Windows.Forms.Button
    $cancelAppearanceButton.Text = "Cancel"
    $cancelAppearanceButton.Location = New-Object System.Drawing.Point(310, 335)
    $cancelAppearanceButton.Size = New-Object System.Drawing.Size(150, 35)
    $appearanceForm.Controls.Add($cancelAppearanceButton)

    $resetAppearanceButton.Add_Click({
        $draftTheme.Background = $script:defaultTheme.Background
        $draftTheme.Foreground = $script:defaultTheme.Foreground
        $draftTheme.Accent = $script:defaultTheme.Accent
        $draftTheme.FontSize = $script:defaultTheme.FontSize
        $draftTheme.Opacity = $script:defaultTheme.Opacity
        $backgroundButton.BackColor = Get-ThemeColor $draftTheme.Background
        $foregroundButton.BackColor = Get-ThemeColor $draftTheme.Foreground
        $accentButton.BackColor = Get-ThemeColor $draftTheme.Accent
        $fontSizeInput.Value = $draftTheme.FontSize
        $opacityInput.Value = $draftTheme.Opacity
    }.GetNewClosure())

    $saveAppearanceButton.Add_Click({
        $oldTheme = $script:theme
        $script:theme = [PSCustomObject]@{
            Background = $draftTheme.Background
            Foreground = $draftTheme.Foreground
            Accent     = $draftTheme.Accent
            FontSize   = [int]$fontSizeInput.Value
            Opacity    = [int]$opacityInput.Value
        }

        try {
            Save-ThemeSettings
            Apply-ApplicationTheme
            $appearanceForm.Close()
        }
        catch {
            $script:theme = $oldTheme
            Apply-ApplicationTheme
            [System.Windows.Forms.MessageBox]::Show(
                "Could not save appearance settings:`n$($_.Exception.Message)",
                "Appearance Settings",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure())

    $cancelAppearanceButton.Add_Click({
        $appearanceForm.Close()
    }.GetNewClosure())

    Apply-ThemeToControl -Control $appearanceForm
    [void]$appearanceForm.ShowDialog($form)
}

$appearanceButton.Add_Click({
    Show-AppearanceWindow
})

