# EDIT MANUAL ASSET WINDOW
# ============================================================

function Show-EditAssetWindow {

    $record = Get-SelectedAssetRecord

    if ($null -eq $record) {
        [System.Windows.Forms.MessageBox]::Show(
            "Select an asset first.",
            "Edit Manual Asset",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )
        return
    }

    if ($record.Source -ne "Manual") {
        [System.Windows.Forms.MessageBox]::Show(
            "Only manually added assets can be edited.",
            "Protected Asset",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        )
        return
    }

    $originalAssetName = [string]$record.AssetName

    $editForm = New-Object System.Windows.Forms.Form
    $editForm.Text = "Edit Manual Asset"
    $editForm.Size = New-Object System.Drawing.Size(620, 520)
    $editForm.StartPosition = "CenterParent"
    $editForm.FormBorderStyle = "FixedDialog"
    $editForm.MaximizeBox = $false
    $editForm.MinimizeBox = $false
    $editForm.BackColor = [System.Drawing.Color]::FromArgb(28, 30, 34)

    $editTitle = New-Object System.Windows.Forms.Label
    $editTitle.Text = "EDIT MANUAL ASSET"
    $editTitle.Location = New-Object System.Drawing.Point(20, 15)
    $editTitle.Size = New-Object System.Drawing.Size(320, 30)
    $editTitle.Font = New-Object System.Drawing.Font(
        "Segoe UI",
        14,
        [System.Drawing.FontStyle]::Bold
    )
    $editTitle.ForeColor = [System.Drawing.Color]::FromArgb(80, 200, 255)
    $editForm.Controls.Add($editTitle)

    $editAssetLabel = New-Object System.Windows.Forms.Label
    $editAssetLabel.Text = "Internal Asset Name"
    $editAssetLabel.Location = New-Object System.Drawing.Point(20, 60)
    $editAssetLabel.AutoSize = $true
    $editAssetLabel.ForeColor = [System.Drawing.Color]::White
    $editForm.Controls.Add($editAssetLabel)

    $editAssetBox = New-Object System.Windows.Forms.TextBox
    $editAssetBox.Location = New-Object System.Drawing.Point(20, 82)
    $editAssetBox.Size = New-Object System.Drawing.Size(560, 25)
    $editAssetBox.Text = [string]$record.AssetName
    $editForm.Controls.Add($editAssetBox)

    $editDisplayLabel = New-Object System.Windows.Forms.Label
    $editDisplayLabel.Text = "Display Name"
    $editDisplayLabel.Location = New-Object System.Drawing.Point(20, 120)
    $editDisplayLabel.AutoSize = $true
    $editDisplayLabel.ForeColor = [System.Drawing.Color]::White
    $editForm.Controls.Add($editDisplayLabel)

    $editDisplayBox = New-Object System.Windows.Forms.TextBox
    $editDisplayBox.Location = New-Object System.Drawing.Point(20, 142)
    $editDisplayBox.Size = New-Object System.Drawing.Size(560, 25)
    $editDisplayBox.Text = [string]$record.DisplayName
    $editForm.Controls.Add($editDisplayBox)

    $editCategoryLabel = New-Object System.Windows.Forms.Label
    $editCategoryLabel.Text = "Category"
    $editCategoryLabel.Location = New-Object System.Drawing.Point(20, 180)
    $editCategoryLabel.AutoSize = $true
    $editCategoryLabel.ForeColor = [System.Drawing.Color]::White
    $editForm.Controls.Add($editCategoryLabel)

    $editCategoryBox = New-Object System.Windows.Forms.ComboBox
    $editCategoryBox.Location = New-Object System.Drawing.Point(20, 202)
    $editCategoryBox.Size = New-Object System.Drawing.Size(265, 25)
    $editCategoryBox.DropDownStyle = "DropDown"

    foreach ($category in @(
        "Animal", "Deviant", "Equipment", "Interactive", "KeyItem",
        "Loot", "Misc", "Monster", "NPC", "Plant", "Resource",
        "Structure", "Vehicle", "Visual", "Weapon", "World", "Unknown"
    )) {
        [void]$editCategoryBox.Items.Add($category)
    }

    $editCategoryBox.Text = [string]$record.Category
    $editForm.Controls.Add($editCategoryBox)

    $editSubLabel = New-Object System.Windows.Forms.Label
    $editSubLabel.Text = "SubCategory"
    $editSubLabel.Location = New-Object System.Drawing.Point(315, 180)
    $editSubLabel.AutoSize = $true
    $editSubLabel.ForeColor = [System.Drawing.Color]::White
    $editForm.Controls.Add($editSubLabel)

    $editSubBox = New-Object System.Windows.Forms.TextBox
    $editSubBox.Location = New-Object System.Drawing.Point(315, 202)
    $editSubBox.Size = New-Object System.Drawing.Size(265, 25)
    $editSubBox.Text = [string]$record.SubCategory
    $editForm.Controls.Add($editSubBox)

    $editNotesLabel = New-Object System.Windows.Forms.Label
    $editNotesLabel.Text = "Notes"
    $editNotesLabel.Location = New-Object System.Drawing.Point(20, 245)
    $editNotesLabel.AutoSize = $true
    $editNotesLabel.ForeColor = [System.Drawing.Color]::White
    $editForm.Controls.Add($editNotesLabel)

    $editNotesBox = New-Object System.Windows.Forms.TextBox
    $editNotesBox.Location = New-Object System.Drawing.Point(20, 267)
    $editNotesBox.Size = New-Object System.Drawing.Size(560, 100)
    $editNotesBox.Multiline = $true
    $editNotesBox.ScrollBars = "Vertical"
    $editNotesBox.Text = [string]$record.Notes
    $editForm.Controls.Add($editNotesBox)

    $editStatusLabel = New-Object System.Windows.Forms.Label
    $editStatusLabel.Location = New-Object System.Drawing.Point(20, 380)
    $editStatusLabel.Size = New-Object System.Drawing.Size(560, 25)
    $editStatusLabel.ForeColor = [System.Drawing.Color]::Yellow
    $editForm.Controls.Add($editStatusLabel)

    $saveEditButton = New-Object System.Windows.Forms.Button
    $saveEditButton.Text = "Save Changes"
    $saveEditButton.Location = New-Object System.Drawing.Point(20, 420)
    $saveEditButton.Size = New-Object System.Drawing.Size(130, 35)
    $editForm.Controls.Add($saveEditButton)

    $cancelEditButton = New-Object System.Windows.Forms.Button
    $cancelEditButton.Text = "Cancel"
    $cancelEditButton.Location = New-Object System.Drawing.Point(160, 420)
    $cancelEditButton.Size = New-Object System.Drawing.Size(100, 35)
    $editForm.Controls.Add($cancelEditButton)

    $saveEditButton.Add_Click({

        $newAssetName = $editAssetBox.Text.Trim()
        $newDisplayName = $editDisplayBox.Text.Trim()
        $newCategory = $editCategoryBox.Text.Trim()
        $newSubCategory = $editSubBox.Text.Trim()
        $newNotes = $editNotesBox.Text.Trim()

        if ([string]::IsNullOrWhiteSpace($newAssetName)) {
            $editStatusLabel.Text = "Asset Name is required."
            $editStatusLabel.ForeColor = [System.Drawing.Color]::Red
            return
        }

        if ([string]::IsNullOrWhiteSpace($newDisplayName)) {
            $newDisplayName = $newAssetName -replace "_", " "
        }

        if ([string]::IsNullOrWhiteSpace($newCategory)) {
            $newCategory = "Unknown"
        }

        if ([string]::IsNullOrWhiteSpace($newSubCategory)) {
            $newSubCategory = "Manual"
        }

        if ($newAssetName -ine $originalAssetName) {
            $nameConflict = @(
                $script:db | Where-Object {
                    $_.AssetName -ieq $newAssetName
                }
            )

            if ($nameConflict.Count -gt 0) {
                $editStatusLabel.Text = "That Asset Name already exists."
                $editStatusLabel.ForeColor = [System.Drawing.Color]::Red
                return
            }
        }

        try {
            $manualRecords = @(
                Import-Csv -LiteralPath $manualDatabaseFile -ErrorAction Stop
            )
        }
        catch {
            $editStatusLabel.Text = "Could not read the manual database."
            $editStatusLabel.ForeColor = [System.Drawing.Color]::Red
            [System.Windows.Forms.MessageBox]::Show(
                "Could not read manual_items.csv:`n$($_.Exception.Message)",
                "Edit Failed",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            )
            return
        }

        $manualRecordIndex = Find-ManualRecordIndex `
            -Record $record `
            -ManualRecords $manualRecords

        if ($manualRecordIndex -lt 0) {
            $editStatusLabel.Text = "Manual record was not found."
            $editStatusLabel.ForeColor = [System.Drawing.Color]::Red
            return
        }

        $manualRecord = $manualRecords[$manualRecordIndex]
        $manualRecord.AssetName = $newAssetName
        $manualRecord.DisplayName = $newDisplayName
        $manualRecord.Category = $newCategory
        $manualRecord.SubCategory = $newSubCategory
        $manualRecord.Source = "Manual"
        $manualRecord.Notes = $newNotes
        $manualRecord.SearchTerms = @(
            $newCategory
            $newSubCategory
            $newAssetName
            $newDisplayName
            $newNotes
        ) -join ";"

        try {
            Save-ManualDatabase -Records $manualRecords
        }
        catch {
            $editStatusLabel.Text = "Could not save changes."
            $editStatusLabel.ForeColor = [System.Drawing.Color]::Red
            [System.Windows.Forms.MessageBox]::Show(
                "Could not save changes to manual_items.csv:`n$($_.Exception.Message)",
                "Save Failed",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            )
            return
        }

        try {
            Reload-AssetDatabase
        }
        catch {
            $editStatusLabel.Text = "Saved, but the database could not be reloaded."
            $editStatusLabel.ForeColor = [System.Drawing.Color]::Red
            [System.Windows.Forms.MessageBox]::Show(
                "Changes were saved, but the combined database could not be reloaded:`n$($_.Exception.Message)",
                "Reload Failed",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            )
            return
        }

        $editForm.Close()
        [System.Windows.Forms.MessageBox]::Show(
            "Manual asset updated successfully.",
            "Asset Updated",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )
    }.GetNewClosure())

    $cancelEditButton.Add_Click({
        $editForm.Close()
    }.GetNewClosure())

    Apply-ThemeToControl -Control $editForm
    [void]$editForm.ShowDialog($form)
}

# ============================================================
# DELETE MANUAL ASSET
# ============================================================

function Remove-SelectedManualAsset {

    $record = Get-SelectedAssetRecord

    if ($null -eq $record) {
        [System.Windows.Forms.MessageBox]::Show(
            "Select an asset first.",
            "Delete Manual Asset",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )
        return
    }

    if ($record.Source -ne "Manual") {
        [System.Windows.Forms.MessageBox]::Show(
            "Only manually added assets can be deleted.",
            "Protected Asset",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        )
        return
    }

    $confirmation = [System.Windows.Forms.MessageBox]::Show(
        "Delete this manual asset?`n`n$($record.DisplayName)`n$($record.AssetName)`n`nYou can undo this deletion until the GUI closes.",
        "Confirm Delete",
        [System.Windows.Forms.MessageBoxButtons]::YesNo,
        [System.Windows.Forms.MessageBoxIcon]::Warning
    )

    if ($confirmation -ne [System.Windows.Forms.DialogResult]::Yes) {
        return
    }

    try {
        $manualRecords = @(
            Import-Csv -LiteralPath $manualDatabaseFile -ErrorAction Stop
        )
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Could not read manual_items.csv:`n$($_.Exception.Message)",
            "Delete Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
        return
    }

    $manualRecordIndex = Find-ManualRecordIndex `
        -Record $record `
        -ManualRecords $manualRecords

    if ($manualRecordIndex -lt 0) {
        [System.Windows.Forms.MessageBox]::Show(
            "The manual record could not be found.",
            "Delete Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
        return
    }

    $remainingRecords = @(
        for ($index = 0; $index -lt $manualRecords.Count; $index++) {
            if ($index -ne $manualRecordIndex) {
                $manualRecords[$index]
            }
        }
    )

    try {
        Save-ManualDatabase -Records $remainingRecords
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Could not delete the manual asset:`n$($_.Exception.Message)",
            "Delete Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
        return
    }

    $script:lastDeletedAsset = [PSCustomObject]@{
        Category    = [string]$record.Category
        SubCategory = [string]$record.SubCategory
        AssetName   = [string]$record.AssetName
        DisplayName = [string]$record.DisplayName
        Source      = "Manual"
        SearchTerms = [string]$record.SearchTerms
        Notes       = [string]$record.Notes
    }
    $undoDeleteButton.Enabled = $true

    try {
        Reload-AssetDatabase
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "The asset was deleted, but the combined database could not be reloaded:`n$($_.Exception.Message)",
            "Reload Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
        return
    }

    $grid.ClearSelection()
    [System.Windows.Forms.MessageBox]::Show(
        "Manual asset deleted successfully.",
        "Asset Deleted",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Information
    )
}

function Undo-LastManualDelete {

    if ($null -eq $script:lastDeletedAsset) {
        [System.Windows.Forms.MessageBox]::Show(
            "There is no deleted manual asset to restore.",
            "Undo Delete",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )
        return
    }

    $assetToRestore = $script:lastDeletedAsset
    $conflict = @(
        $script:db | Where-Object {
            $_.AssetName -ieq $assetToRestore.AssetName
        }
    )

    if ($conflict.Count -gt 0) {
        [System.Windows.Forms.MessageBox]::Show(
            "Cannot restore the deleted asset because an asset with the same internal name already exists:`n`n$($assetToRestore.AssetName)",
            "Undo Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        )
        return
    }

    try {
        $manualRecords = @(
            Import-Csv -LiteralPath $manualDatabaseFile -ErrorAction Stop |
                Where-Object {
                    -not [string]::IsNullOrWhiteSpace($_.AssetName)
                }
        )

        Save-ManualDatabase -Records @(
            $manualRecords
            $assetToRestore
        )
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Could not restore the deleted manual asset:`n$($_.Exception.Message)",
            "Undo Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
        return
    }

    try {
        Reload-AssetDatabase
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "The asset was restored, but the combined database could not be reloaded:`n$($_.Exception.Message)",
            "Reload Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
        return
    }

    $restoredName = [string]$assetToRestore.DisplayName
    $restoredAssetName = [string]$assetToRestore.AssetName
    $script:lastDeletedAsset = $null
    $undoDeleteButton.Enabled = $false

    [System.Windows.Forms.MessageBox]::Show(
        "Deletion undone successfully.`n`n$restoredName`n$restoredAssetName",
        "Asset Restored",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Information
    )
}

$editAssetButton.Add_Click({
    Show-EditAssetWindow
})

$deleteAssetButton.Add_Click({
    Remove-SelectedManualAsset
})

$undoDeleteButton.Add_Click({
    Undo-LastManualDelete
})

# ============================================================
# MAP INTERACTIONS
# ============================================================

$mapCanvas.Add_Paint({
    param($sender, $eventArgs)

    $graphics = $eventArgs.Graphics
    $graphics.Clear($sender.BackColor)

    if ($null -eq $script:activeMapImage) {
        $emptyMessage = "Import a map image to get started."
        $emptyFont = New-Object System.Drawing.Font("Segoe UI", 12)
        $emptyBrush = New-Object System.Drawing.SolidBrush(
            (Get-ThemeColor $script:theme.Foreground)
        )
        try {
            $textSize = $graphics.MeasureString($emptyMessage, $emptyFont)
            $graphics.DrawString(
                $emptyMessage,
                $emptyFont,
                $emptyBrush,
                [single](($sender.ClientSize.Width - $textSize.Width) / 2),
                [single](($sender.ClientSize.Height - $textSize.Height) / 2)
            )
        }
        finally {
            $emptyBrush.Dispose()
            $emptyFont.Dispose()
        }
        return
    }

    $imageRectangle = Get-MapImageRectangle `
        -Canvas $sender `
        -Image $script:activeMapImage `
        -Zoom $script:mapZoom `
        -PanX $script:mapPanX `
        -PanY $script:mapPanY
    $graphics.DrawImage($script:activeMapImage, $imageRectangle)

    $selectedMarkerId = $null
    if ($mapMarkerList.SelectedItems.Count -gt 0) {
        $selectedMarkerId = [string]$mapMarkerList.SelectedItems[0].Tag
    }

    foreach ($marker in @(Get-VisibleMapMarkers)) {
        $markerX = [double]::Parse(
            [string]$marker.X,
            [Globalization.CultureInfo]::InvariantCulture
        )
        $markerY = [double]::Parse(
            [string]$marker.Y,
            [Globalization.CultureInfo]::InvariantCulture
        )
        $diameter = if ([string]$marker.MarkerId -eq $selectedMarkerId) { 18 } else { 14 }
        $pinCenterX = [single]($imageRectangle.X + ($markerX * $imageRectangle.Width))
        $pinCenterY = [single]($imageRectangle.Y + ($markerY * $imageRectangle.Height))
        $pinRectangle = New-Object System.Drawing.RectangleF(
            ($pinCenterX - ($diameter / 2)),
            ($pinCenterY - ($diameter / 2)),
            $diameter,
            $diameter
        )
        $pinColor = if ([string]$marker.MarkerId -eq $selectedMarkerId) {
            Get-ThemeColor $script:theme.Accent
        }
        else {
            [System.Drawing.Color]::FromArgb(220, 210, 45, 45)
        }
        $pinBrush = New-Object System.Drawing.SolidBrush($pinColor)
        $pinPen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 2)
        try {
            $graphics.FillEllipse($pinBrush, $pinRectangle)
            $graphics.DrawEllipse($pinPen, $pinRectangle)

            if ([string]$marker.MarkerId -eq $selectedMarkerId) {
                $labelFont = New-Object System.Drawing.Font("Segoe UI", 9)
                $labelBrush = New-Object System.Drawing.SolidBrush(
                    (Get-ThemeColor $script:theme.Foreground)
                )
                try {
                    $graphics.DrawString(
                        [string]$marker.Name,
                        $labelFont,
                        $labelBrush,
                        ($pinCenterX + 10),
                        ($pinCenterY + 6)
                    )
                }
                finally {
                    $labelBrush.Dispose()
                    $labelFont.Dispose()
                }
            }
        }
        finally {
            $pinPen.Dispose()
            $pinBrush.Dispose()
        }
    }
})

$mapCanvas.Add_MouseClick({
    param($sender, $eventArgs)

    if ($eventArgs.Button -ne [System.Windows.Forms.MouseButtons]::Left -or
        -not $script:isPlacingMapMarker -or
        $null -eq $script:activeMapImage) {
        return
    }

    $imageRectangle = Get-MapImageRectangle `
        -Canvas $sender `
        -Image $script:activeMapImage `
        -Zoom $script:mapZoom `
        -PanX $script:mapPanX `
        -PanY $script:mapPanY
    if (-not $imageRectangle.Contains([single]$eventArgs.X, [single]$eventArgs.Y)) {
        return
    }

    $markerX = ($eventArgs.X - $imageRectangle.X) / $imageRectangle.Width
    $markerY = ($eventArgs.Y - $imageRectangle.Y) / $imageRectangle.Height
    $script:isPlacingMapMarker = $false
    $placeMapMarkerButton.Text = "Place Marker"
    Show-MapMarkerDialog -X $markerX -Y $markerY
})

$mapCanvas.Add_MouseDown({
    param($sender, $eventArgs)

    if ($eventArgs.Button -ne [System.Windows.Forms.MouseButtons]::Left -or
        $script:isPlacingMapMarker -or
        $null -eq $script:activeMapImage) {
        return
    }

    $script:isPanningMap = $true
    $script:mapPanStart = [System.Drawing.Point]::new($eventArgs.X, $eventArgs.Y)
    $script:mapPanStartOffsetX = $script:mapPanX
    $script:mapPanStartOffsetY = $script:mapPanY
    $script:mapPanDragged = $false
    $sender.Cursor = [System.Windows.Forms.Cursors]::Hand
})

$mapCanvas.Add_MouseMove({
    param($sender, $eventArgs)

    if (-not $script:isPanningMap) {
        return
    }

    $deltaX = $eventArgs.X - $script:mapPanStart.X
    $deltaY = $eventArgs.Y - $script:mapPanStart.Y
    if ([Math]::Abs($deltaX) -gt 3 -or [Math]::Abs($deltaY) -gt 3) {
        $script:mapPanDragged = $true
    }

    if ($script:mapPanDragged) {
        $script:mapPanX = $script:mapPanStartOffsetX + $deltaX
        $script:mapPanY = $script:mapPanStartOffsetY + $deltaY
        $sender.Invalidate()
    }
})

$mapCanvas.Add_MouseUp({
    param($sender, $eventArgs)

    if ($eventArgs.Button -ne [System.Windows.Forms.MouseButtons]::Left -or
        -not $script:isPanningMap) {
        return
    }

    $script:isPanningMap = $false
    $sender.Cursor = [System.Windows.Forms.Cursors]::Default
    if ($script:mapPanDragged -or $null -eq $script:activeMapImage) {
        return
    }

    $imageRectangle = Get-MapImageRectangle `
        -Canvas $sender `
        -Image $script:activeMapImage `
        -Zoom $script:mapZoom `
        -PanX $script:mapPanX `
        -PanY $script:mapPanY
    $closestMarkerId = $null
    $closestDistanceSquared = 18 * 18
    foreach ($marker in @(Get-VisibleMapMarkers)) {
        $markerX = [double]::Parse(
            [string]$marker.X,
            [Globalization.CultureInfo]::InvariantCulture
        )
        $markerY = [double]::Parse(
            [string]$marker.Y,
            [Globalization.CultureInfo]::InvariantCulture
        )
        $screenX = $imageRectangle.X + ($markerX * $imageRectangle.Width)
        $screenY = $imageRectangle.Y + ($markerY * $imageRectangle.Height)
        $distanceSquared = [Math]::Pow($eventArgs.X - $screenX, 2) +
            [Math]::Pow($eventArgs.Y - $screenY, 2)
        if ($distanceSquared -le $closestDistanceSquared) {
            $closestDistanceSquared = $distanceSquared
            $closestMarkerId = [string]$marker.MarkerId
        }
    }

    if ($null -ne $closestMarkerId) {
        foreach ($listItem in $mapMarkerList.Items) {
            if ([string]$listItem.Tag -eq $closestMarkerId) {
                $listItem.Selected = $true
                $listItem.Focused = $true
                $listItem.EnsureVisible()
                break
            }
        }
    }
})

$mapCanvas.Add_MouseWheel({
    param($sender, $eventArgs)

    if ($null -eq $script:activeMapImage) {
        return
    }

    $wheelSteps = $eventArgs.Delta / 120.0
    Set-MapZoom `
        -Zoom ($script:mapZoom * [Math]::Pow(1.2, $wheelSteps)) `
        -FocusX $eventArgs.X `
        -FocusY $eventArgs.Y
})

$mapCanvas.Add_DragEnter({
    param($sender, $eventArgs)

    if ($eventArgs.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) {
        $eventArgs.Effect = [System.Windows.Forms.DragDropEffects]::Copy
    }
    else {
        $eventArgs.Effect = [System.Windows.Forms.DragDropEffects]::None
    }
})

$mapCanvas.Add_DragDrop({
    param($sender, $eventArgs)

    $droppedPaths = [string[]]$eventArgs.Data.GetData(
        [System.Windows.Forms.DataFormats]::FileDrop
    )
    if ($droppedPaths.Count -eq 0) {
        return
    }

    $extension = [IO.Path]::GetExtension($droppedPaths[0]).ToLowerInvariant()
    if ($extension -notin @(".png", ".jpg", ".jpeg", ".bmp", ".gif", ".tif", ".tiff")) {
        [System.Windows.Forms.MessageBox]::Show(
            "Drop a supported image file (PNG, JPG, BMP, GIF, or TIFF).",
            "Unsupported Map Image",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        ) | Out-Null
        return
    }

    Show-MapImportDialog -ImagePath $droppedPaths[0]
})

$mapSelector.Add_SelectedIndexChanged({
    Load-SelectedMap
})

$mapMarkerList.Add_SelectedIndexChanged({
    if ($mapMarkerList.SelectedItems.Count -eq 0) {
        $mapMarkerDetails.Clear()
        $deleteMapMarkerButton.Enabled = $false
        $mapCanvas.Invalidate()
        return
    }

    $markerId = [string]$mapMarkerList.SelectedItems[0].Tag
    $marker = $script:mapMarkers |
        Where-Object { $_.MarkerId -eq $markerId } |
        Select-Object -First 1

    if ($null -eq $marker) {
        $mapMarkerDetails.Clear()
        $deleteMapMarkerButton.Enabled = $false
        return
    }

    $mapMarkerDetails.Text = @(
        "Name: $($marker.Name)"
        "Type / status: $($marker.Type)"
        "Notes: $($marker.Notes)"
    ) -join [Environment]::NewLine
    $deleteMapMarkerButton.Enabled = $true
    $mapCanvas.Invalidate()
})

$mapMarkerSearch.Add_TextChanged({
    Update-MapMarkerList
})

$mapCanvas.Add_MouseEnter({
    $mapCanvas.Focus()
})

$placeMapMarkerButton.Add_Click({
    if ($null -eq $script:activeMap) {
        return
    }

    $script:isPlacingMapMarker = -not $script:isPlacingMapMarker
    if ($script:isPlacingMapMarker) {
        $placeMapMarkerButton.Text = "Click Map..."
    }
    else {
        $placeMapMarkerButton.Text = "Place Marker"
    }
})

$mapZoomInButton.Add_Click({
    Set-MapZoom -Zoom ($script:mapZoom * 1.25)
})

$mapZoomOutButton.Add_Click({
    Set-MapZoom -Zoom ($script:mapZoom / 1.25)
})

$mapFitButton.Add_Click({
    $script:mapZoom = 1.0
    $script:mapPanX = 0.0
    $script:mapPanY = 0.0
    $mapCanvas.Invalidate()
})

$importMapButton.Add_Click({
    $openDialog = New-Object System.Windows.Forms.OpenFileDialog
    $openDialog.Title = "Import a Map Image"
    $openDialog.Filter = "Map images (*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff)|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff|All files (*.*)|*.*"
    $openDialog.CheckFileExists = $true

    if ($openDialog.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
        Show-MapImportDialog -ImagePath $openDialog.FileName
    }
    $openDialog.Dispose()
})

$deleteMapMarkerButton.Add_Click({
    if ($mapMarkerList.SelectedItems.Count -eq 0) {
        return
    }

    $markerId = [string]$mapMarkerList.SelectedItems[0].Tag
    $answer = [System.Windows.Forms.MessageBox]::Show(
        "Delete the selected map marker?",
        "Delete Map Marker",
        [System.Windows.Forms.MessageBoxButtons]::YesNo,
        [System.Windows.Forms.MessageBoxIcon]::Question
    )
    if ($answer -ne [System.Windows.Forms.DialogResult]::Yes) {
        return
    }

    $updatedMarkers = @(
        $script:mapMarkers | Where-Object { $_.MarkerId -ne $markerId }
    )
    try {
        Save-MapCsv `
            -Path $mapMarkersFile `
            -Columns @("MarkerId", "MapId", "Name", "Type", "Notes", "X", "Y", "DateAdded") `
            -Records $updatedMarkers
        $script:mapMarkers = $updatedMarkers
        Update-MapMarkerList
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Could not delete the map marker:`n$($_.Exception.Message)",
            "Marker Delete Failed",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
    }
})

function Show-OnlineMap {

    param(
        [Parameter(Mandatory = $true)]
        [uri]$Url
    )

    $mapCanvas.Visible = $false
    $onlineMapHost.Visible = $true
    $onlineMapHost.BringToFront()

    if (-not $script:webView2Available -or
        $null -eq $script:onlineMapBrowser) {
        $onlineMapStatus.Visible = $true
        $onlineMapStatus.Text = "Online map view unavailable: $($script:webView2LoadError)"
        return
    }

    $script:pendingOnlineMapUrl = $Url.AbsoluteUri

    if ($null -ne $script:onlineMapBrowser.CoreWebView2) {
        try {
            $onlineMapStatus.Visible = $true
            $onlineMapStatus.Text = "Loading online map..."
            $script:onlineMapBrowser.CoreWebView2.Navigate(
                $script:pendingOnlineMapUrl
            )
        }
        catch {
            $onlineMapStatus.Visible = $true
            $onlineMapStatus.Text = "Could not navigate to the online map: $($_.Exception.Message)"
        }
        return
    }

    if ($script:onlineMapInitializationStarted) {
        $onlineMapStatus.Visible = $true
        $onlineMapStatus.Text = "Starting the embedded browser..."
        return
    }

    $script:onlineMapInitializationStarted = $true
    $onlineMapStatus.Visible = $true
    $onlineMapStatus.Text = "Starting the embedded browser..."

    $script:onlineMapBrowser.Add_CoreWebView2InitializationCompleted({
        param($sender, $eventArgs)

        if (-not $eventArgs.IsSuccess) {
            $script:webView2LoadError = [string]$eventArgs.InitializationException.Message
            $onlineMapStatus.Visible = $true
            $onlineMapStatus.Text = "WebView2 could not start: $($script:webView2LoadError)"
            return
        }

        $onlineMapBackButton.Enabled = $true
        $onlineMapForwardButton.Enabled = $true
        $onlineMapReloadButton.Enabled = $true

        $sender.CoreWebView2.Add_NavigationStarting({
            $onlineMapStatus.Visible = $true
            $onlineMapStatus.Text = "Loading online map..."
        })

        $sender.CoreWebView2.Add_NavigationCompleted({
            param($browserSender, $navigationArgs)

            if ($navigationArgs.IsSuccess) {
                $onlineMapStatus.Visible = $false
            }
            else {
                $onlineMapStatus.Visible = $true
                $onlineMapStatus.Text = "The online map did not load ($($navigationArgs.WebErrorStatus)). Check your connection or reload."
            }

            $onlineMapBackButton.Enabled = $browserSender.CanGoBack
            $onlineMapForwardButton.Enabled = $browserSender.CanGoForward
        })

        if (-not [string]::IsNullOrWhiteSpace($script:pendingOnlineMapUrl)) {
            $sender.CoreWebView2.Navigate($script:pendingOnlineMapUrl)
        }
    })

    try {
        $script:onlineMapBrowser.EnsureCoreWebView2Async() | Out-Null
    }
    catch {
        $script:webView2LoadError = $_.Exception.Message
        $onlineMapStatus.Visible = $true
        $onlineMapStatus.Text = "WebView2 could not start: $($script:webView2LoadError)"
        $script:onlineMapInitializationStarted = $false
    }
}

$onlineMapBackButton.Add_Click({
    if ($null -ne $script:onlineMapBrowser.CoreWebView2 -and
        $script:onlineMapBrowser.CoreWebView2.CanGoBack) {
        $script:onlineMapBrowser.CoreWebView2.GoBack()
    }
})

$onlineMapForwardButton.Add_Click({
    if ($null -ne $script:onlineMapBrowser.CoreWebView2 -and
        $script:onlineMapBrowser.CoreWebView2.CanGoForward) {
        $script:onlineMapBrowser.CoreWebView2.GoForward()
    }
})

$onlineMapReloadButton.Add_Click({
    if ($null -ne $script:onlineMapBrowser.CoreWebView2) {
        $script:onlineMapBrowser.CoreWebView2.Reload()
    }
})

$offlineMapViewButton.Add_Click({
    $onlineMapHost.Visible = $false
    $mapCanvas.Visible = $true
    $mapCanvas.BringToFront()
})

$openOnceHumanMapButton.Add_Click({
    Show-OnlineMap -Url "https://www.oncehumandb.com/map"
})

$openMapGenieButton.Add_Click({
    Show-OnlineMap -Url "https://mapgenie.io/once-human/maps/nalcott?x=-0.47099754573227415&y=0.4641109038569198&zoom=11.000000000000004"
})

$openThMapsButton.Add_Click({
    Show-OnlineMap -Url "https://oncehuman.th.gl/maps"
})

